/** The country's photographs, best known first, or [] when it has none. */
export function countryPhotos(cc) {
  return COUNTRY_GALLERY[String(cc || '').toUpperCase()] || [];
}

/** The i18n key of the line under a country's name, or null. */
export function countryKnownKey(cc) {
  const k = String(cc || '').toUpperCase();
  return COUNTRY_GALLERY[k] ? `country.known.${k}` : null;
}
